<script setup>
import {ref,onMounted} from 'vue'
import {request} from './client'
import FirebasePush from './FirebasePush.vue'
import './release.css'
const props=defineProps({compact:Boolean,profile:{type:String,default:''}})
const emit=defineEmits(['unread'])
const device=ref(sessionStorage.getItem('sisu-push-device')||'')
const rows=ref([]),config=ref(null),count=ref(0),page=ref(0),error=ref(''),busy=ref(false),note=ref('')
async function run(fn){busy.value=true;error.value='';note.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function load(){const result=await Promise.all([request('notification_service','inbox',{page:page.value,profile:props.profile}),request('release','unread',{profile:props.profile},'GET')]);rows.value=result[0];count.value=result[1].count;emit('unread',count.value);if(!props.compact){try{config.value=await request('release','channels',{},'GET')}catch{config.value=null}}}
const when=value=>{const d=new Date(String(value).replace(' ','T')+'+05:30');return isNaN(d)?value:d.toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'})}

async function read(n){await run(async()=>{await request('notification_service','mark_read',{name:n.name});await load()})}
async function save(){await run(async()=>{await request('notification_service','save_preferences',{settings:{...config.value.settings,channels:config.value.preferences}});note.value='Preferences saved. Verified contact details and provider delivery rules still apply.'})}
async function push(){await run(async()=>{if(!config.value.browser_push_available||typeof window.sisuPushAdapter?.register!=='function')throw Error('Browser push adapter is not installed/configured. No token was registered.');const result=await window.sisuPushAdapter.register();const saved=await request('devices','register',{device_id:result.device_id,token:result.token,platform:'web'});device.value=saved.device;sessionStorage.setItem('sisu-push-device',saved.device);note.value='Device token registered. Provider delivery acceptance still requires testing.'})}
async function revoke(){await run(async()=>{await request('devices','revoke',{device:device.value});device.value='';sessionStorage.removeItem('sisu-push-device');note.value='Device token revoked on this site.'})}
onMounted(()=>run(load))
</script>
<template><section class="release notification-center" :class="{compact}"><h1>Notifications <span class="badge">{{count}} unread</span></h1><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="note" role="status">{{note}}</p><p v-if="busy" role="status">Loading…</p><button class="button subtle" :disabled="busy" @click="run(load)">Refresh</button><article v-for="n in (compact?rows.slice(0,6):rows)" :key="n.name" class="panel notification-card" :class="{unread:!n.read_at}"><p>{{n.body}}</p><small>{{when(n.creation)}} · {{n.read_at?'Read':'Unread'}}</small><button v-if="!n.read_at" class="button primary mark-read" :disabled="busy" @click="read(n)">Mark as read</button></article><p v-if="!busy&&!rows.length">No notifications on this page.</p><button class="button subtle" v-if="!compact" :disabled="busy||page===0" @click="page--;run(load)">Previous</button><button class="button subtle" v-if="!compact" :disabled="busy||rows.length<50" @click="page++;run(load)">Next</button><FirebasePush v-if="!compact"/><form v-if="config" class="panel" @submit.prevent="save"><h2>Delivery preferences</h2><label v-for="(available,c) in config.available" :key="c" class="check"><input type="checkbox" v-model="config.preferences[c]" :disabled="!available">{{c}} · {{available?'Configured and entitled':'Unavailable — configuration or plan required'}}</label><p>Email/WhatsApp also require verified contact details and contact consent in Settings. Configured does not mean provider-tested.</p><button class="button primary" :disabled="busy">Save preferences</button><button type="button" class="button subtle" :disabled="busy||!config.browser_push_available" @click="push">Register this browser for push</button><button v-if="device" type="button" class="button subtle" :disabled="busy" @click="revoke">Revoke this browser token</button></form></section></template>

<style>.notification-center h1{font-size:24px;display:flex;align-items:center;gap:12px}.notification-center.compact h1{font-size:19px}.notification-card{padding:18px!important;margin:12px 0;border:1px solid var(--student-border,#e8e0ef);border-radius:14px}.notification-card.unread{border-left:4px solid #7850b2;background:var(--student-soft,#f7f2fc)}.notification-card p{line-height:1.65;margin:0 0 8px}.notification-card small{display:block;margin-bottom:12px}.notification-center .mark-read{background:#592c91!important;color:white!important;border:0;padding:8px 13px;border-radius:9px;cursor:pointer}.notification-center.compact .notification-card{font-size:13px}</style>
